CREATE TABLE IF NOT EXISTS planes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,nombre VARCHAR(80) NOT NULL,precio_mensual NUMERIC(10,2) NOT NULL,max_equipos INTEGER NOT NULL,indicadores BOOLEAN NOT NULL DEFAULT FALSE,reportes_exportables BOOLEAN NOT NULL DEFAULT FALSE,multiples_sedes BOOLEAN NOT NULL DEFAULT FALSE,soporte_prioritario BOOLEAN NOT NULL DEFAULT FALSE,activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS suscripciones (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,empresa_id BIGINT NOT NULL REFERENCES empresas(id),plan_id BIGINT NOT NULL REFERENCES planes(id),estado VARCHAR(25) NOT NULL DEFAULT 'prueba',inicio TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,fin_prueba TIMESTAMPTZ,proximo_cobro TIMESTAMPTZ,fecha_cancelacion TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS pagos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,empresa_id BIGINT NOT NULL REFERENCES empresas(id),suscripcion_id BIGINT NOT NULL REFERENCES suscripciones(id),monto NUMERIC(10,2) NOT NULL,moneda VARCHAR(3) NOT NULL DEFAULT 'PEN',metodo VARCHAR(40) NOT NULL DEFAULT 'Transferencia',referencia VARCHAR(120),estado VARCHAR(25) NOT NULL DEFAULT 'pendiente',pagado_en TIMESTAMPTZ,creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO planes (codigo,nombre,precio_mensual,max_equipos,indicadores,reportes_exportables,multiples_sedes,soporte_prioritario) VALUES ('basico','Basico',99,10,FALSE,FALSE,FALSE,FALSE),('flota','Flota',249,30,TRUE,TRUE,FALSE,FALSE),('pro','Pro',449,50,TRUE,TRUE,TRUE,TRUE) ON CONFLICT (codigo) DO UPDATE SET nombre=EXCLUDED.nombre,precio_mensual=EXCLUDED.precio_mensual,max_equipos=EXCLUDED.max_equipos,indicadores=EXCLUDED.indicadores,reportes_exportables=EXCLUDED.reportes_exportables,multiples_sedes=EXCLUDED.multiples_sedes,soporte_prioritario=EXCLUDED.soporte_prioritario;
CREATE INDEX IF NOT EXISTS ix_suscripciones_empresa_estado ON suscripciones(empresa_id,estado);
